ARRIVALS = [2, 9, 5, 17, 0]


def count_late(minutes):
    """Return how many of the arrival times are greater than 5."""
    count = 0
    for minute in minutes:
        if minute > 5:
            count = count + 1
    return count


def main():
    print(count_late(ARRIVALS))


if __name__ == "__main__":
    main()
